import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}

  async *stream(): AsyncGenerator<string> {
    let lease: Lease | undefined;
    let failed = false;

    try {
      lease = await this.source.open();

      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      if (lease !== undefined) {
        if (failed) {
          try {
            await lease.close();
          } catch {
            // Keep the original read, mapper or injected error.
          }
        } else {
          await lease.close();
        }
      }
    }
  }
}
```

