import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}

  async *stream(): AsyncGenerator<string> {
    let lease: Lease | undefined;
    let failed = false;

    try {
      // Opening happens lazily: the generator body only starts on the first
      // next() call, so an unopened generator never touches the source.
      lease = await this.source.open();

      for (;;) {
        // Exactly one read per next(); no read-ahead while suspended at yield.
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      if (lease !== undefined) {
        if (failed) {
          try {
            await lease.close();
          } catch {
            // A read, mapper or injected failure is already in flight:
            // preserve it instead of replacing it with the close failure.
          }
        } else {
          await lease.close();
        }
      }
    }
  }
}
