const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');

// Builds a fake Source (the interface from src/source.ts) that records
// opens/reads/closes and can be told to fail at any point.
function makeSource(values, options = {}) {
  const state = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      state.opens += 1;
      if (options.openError) throw options.openError;
      return {
        async read() {
          state.reads += 1;
          if (options.readError) throw options.readError;
          return values.length === 0 ? null : values.shift();
        },
        async close() {
          state.closes += 1;
          if (options.closeError) throw options.closeError;
        },
      };
    },
  };
  return { source, state };
}

async function main() {
  // Normal exhaustion: mapped records in order, one open, one close.
  {
    const { source, state } = makeSource(['a', 'b', 'c']);
    const service = new EventService(source);
    const found = [];
    for await (const value of service.stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B', 'C']);
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 4); // three values plus the read establishing exhaustion
    assert.equal(state.closes, 1);
  }

  // Returning an unopened generator must not open, read or close anything.
  {
    const { source, state } = makeSource(['a']);
    const service = new EventService(source);
    const iterator = service.stream();
    assert.deepEqual(await iterator.return('unused'), { value: 'unused', done: true });
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // No read-ahead: every next() performs exactly one read (the last read
  // establishes exhaustion); close happens before the done result resolves.
  {
    const { source, state } = makeSource(['a', 'b']);
    const service = new EventService(source);
    const iterator = service.stream();
    assert.equal(state.reads, 0);
    assert.deepEqual(await iterator.next(), { value: 'A', done: false });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 0);
    assert.deepEqual(await iterator.next(), { value: 'B', done: false });
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 0);
    assert.deepEqual(await iterator.next(), { value: undefined, done: true });
    assert.equal(state.reads, 3);
    assert.equal(state.closes, 1);
    assert.deepEqual(await iterator.next(), { value: undefined, done: true });
    assert.equal(state.reads, 3);
    assert.equal(state.closes, 1);
  }

  // Consumer break: closes exactly once and does not read ahead first.
  {
    const { source, state } = makeSource(['a', 'b', 'c']);
    const service = new EventService(source);
    const found = [];
    for await (const value of service.stream()) {
      found.push(value);
      break;
    }
    assert.deepEqual(found, ['A']);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Explicit return(value): closes exactly once, return value preserved.
  {
    const { source, state } = makeSource(['a', 'b']);
    const service = new EventService(source);
    const iterator = service.stream();
    await iterator.next();
    assert.deepEqual(await iterator.return('bye'), { value: 'bye', done: true });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Source read failure: closed exactly once, read error preserved.
  {
    const readError = new Error('read failed');
    const { source, state } = makeSource([], { readError });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === readError,
    );
    assert.equal(state.closes, 1);
  }

  // Read failure AND close failure: original read error wins, closed once.
  {
    const readError = new Error('read failed');
    const { source, state } = makeSource([], { readError, closeError: new Error('close failed') });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === readError,
    );
    assert.equal(state.closes, 1);
  }

  // Mapper failure: closed exactly once, mapper error preserved.
  {
    const mapperError = new Error('mapper failed');
    const { source, state } = makeSource(['a']);
    const service = new EventService(source, () => { throw mapperError; });
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === mapperError,
    );
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Mapper failure AND close failure: original mapper error wins.
  {
    const mapperError = new Error('mapper failed');
    const { source, state } = makeSource(['a'], { closeError: new Error('close failed') });
    const service = new EventService(source, () => { throw mapperError; });
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === mapperError,
    );
    assert.equal(state.closes, 1);
  }

  // Consumer-injected throw: closed exactly once, injected error preserved.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a', 'b']);
    const service = new EventService(source);
    const iterator = service.stream();
    assert.deepEqual(await iterator.next(), { value: 'A', done: false });
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Injected throw AND close failure: the injected error wins.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a'], { closeError: new Error('close failed') });
    const service = new EventService(source);
    const iterator = service.stream();
    await iterator.next();
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.closes, 1);
  }

  // Close failure on normal exhaustion propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a'], { closeError });
    const service = new EventService(source);
    const iterator = service.stream();
    assert.deepEqual(await iterator.next(), { value: 'A', done: false });
    await assert.rejects(iterator.next(), (error) => error === closeError);
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 1);
  }

  // Close failure on consumer break propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a', 'b'], { closeError });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) break; })(),
      (error) => error === closeError,
    );
    assert.equal(state.closes, 1);
  }

  // Close failure on consumer return propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a'], { closeError });
    const service = new EventService(source);
    const iterator = service.stream();
    await iterator.next();
    await assert.rejects(iterator.return(), (error) => error === closeError);
    assert.equal(state.closes, 1);
  }

  // A throw() into an unopened generator must not open, read or close anything.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a']);
    const service = new EventService(source);
    const iterator = service.stream();
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // Open failure leaves nothing to close.
  {
    const openError = new Error('open failed');
    const { source, state } = makeSource(['a'], { openError });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === openError,
    );
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }
}

module.exports = main();
